//! Saved-route preparation + worker-only topology resolution. No pixels/audio.
use super::{Error,Monitor};use skylive_core::{StudioSnapshot,SavedProjectorWindows,SavedProjectorWindow,SavedProjectorTarget as Target,ProjectorWindowGeometry as Geometry};use serde::Serialize;
#[derive(Clone,Debug,Serialize)]#[serde(rename_all="snake_case")]pub enum IssueKind{MissingTarget,AudioOnlyTarget,MonitorMissing,GeometryRelocated,MonitorDiscoveryUnavailable,FullscreenReplaced}
#[derive(Clone,Debug,Serialize)]pub struct Issue{pub index:Option<u8>,pub kind:IssueKind,pub monitor:Option<String>,pub detail:String}
#[derive(Clone,Debug)]pub struct Prepared{session:u64,revision:u64,saved:SavedProjectorWindows,eligible:Vec<bool>,limit_fullscreen:bool,issues:Vec<Issue>}
impl Prepared{pub fn session(&self)->u64{self.session}pub fn revision(&self)->u64{self.revision}pub fn saved(&self)->&SavedProjectorWindows{&self.saved}pub fn snapshot(&self)->PreparationSnapshot{PreparationSnapshot{session:self.session,revision:self.revision,saved:self.saved.clone(),eligible:self.eligible.clone(),issues:self.issues.clone()}}}
#[derive(Clone,Debug,Serialize)]pub struct PreparationSnapshot{pub session:u64,pub revision:u64,pub saved:SavedProjectorWindows,pub eligible:Vec<bool>,pub issues:Vec<Issue>}
#[derive(Clone,Debug)]pub struct Window{pub saved:SavedProjectorWindow,pub monitor:Option<String>,pub geometry:Option<Geometry>}
#[derive(Clone,Debug)]pub struct Resolved{pub prepared:Prepared,pub monitors:Vec<Monitor>,pub windows:Vec<Window>,pub issues:Vec<Issue>}
pub fn prepare(session:u64,model:&StudioSnapshot)->Result<Prepared,Error>{if session==0{return Err(Error::Invalid("projector restore session"));}let saved=model.saved_projectors().clone();let mut eligible=Vec::with_capacity(4);let mut issues=Vec::with_capacity(4);for(index,window)in saved.entries().iter().enumerate(){let problem=match window.target(){Target::Scene{scene}=>model.scene(scene).is_none().then_some(IssueKind::MissingTarget),Target::Source{source}=>match model.source(source){None=>Some(IssueKind::MissingTarget),Some(value)=>if model.source_video_dimensions(value.kind()).map_err(|error|Error::Backend(error.to_string()))?.is_none(){Some(IssueKind::AudioOnlyTarget)}else{None}},_=>None};eligible.push(problem.is_none());if let Some(kind)=problem{issues.push(Issue{index:Some(index as u8),kind,monitor:window.monitor().map(str::to_owned),detail:"The saved collection-local projector target is unavailable; no replacement source is created.".into()});}}Ok(Prepared{session,revision:model.revision(),saved,eligible,limit_fullscreen:model.preferences().projectors().limit_fullscreen_per_monitor(),issues})}
fn contains(m:&Monitor,g:Geometry)->bool{let(x,y)=(i64::from(g.x()),i64::from(g.y()));x>=i64::from(m.x)&&y>=i64::from(m.y)&&x+i64::from(g.width())<=i64::from(m.x)+i64::from(m.width)&&y+i64::from(g.height())<=i64::from(m.y)+i64::from(m.height)}
fn fallback(monitors:&[Monitor],geometry:Option<Geometry>)->Option<Geometry>{let monitor=monitors.iter().find(|m|m.primary&&m.width>=128&&m.height>=128).or_else(||monitors.iter().find(|m|m.width>=128&&m.height>=128))?;let width=geometry.map_or(960,Geometry::width).min(monitor.width.saturating_sub(64)).max(64);let height=geometry.map_or(540,Geometry::height).min(monitor.height.saturating_sub(64)).max(64);let x=i64::from(monitor.x)+i64::from(monitor.width-width)/2;let y=i64::from(monitor.y)+i64::from(monitor.height-height)/2;Geometry::new(i32::try_from(x).ok()?,i32::try_from(y).ok()?,width,height).ok()}
/// Invoke on existing I/O owner. Failure still resolves bounded WINDOWED routes
/// with explicit issues and backend placement, never a fabricated display.
pub fn discover(prepared:Prepared)->Result<Resolved,Error>{resolve(prepared,super::enumerate_monitors())}
pub fn resolve(prepared:Prepared,monitors:Result<Vec<Monitor>,Error>)->Result<Resolved,Error>{let mut issues=prepared.issues.clone();let monitors=match monitors{Ok(value)=>value,Err(error)=>{eprintln!("Projector restore monitor discovery: {error}");issues.push(Issue{index:None,kind:IssueKind::MonitorDiscoveryUnavailable,monitor:None,detail:error.to_string()});Vec::new()}};if monitors.len()>64||monitors.iter().any(|m|m.id.is_empty()||m.id.len()>4096||m.name.len()>4096||m.width==0||m.height==0||m.scale.is_some_and(|s|!s.is_finite()||s<=0.0||s>16.0)){return Err(Error::Invalid("projector restore monitor metadata"));}let mut ids=std::collections::HashSet::new();if monitors.iter().any(|m|!ids.insert(&m.id)){return Err(Error::Invalid("projector restore duplicate monitor identity"));}
 let mut windows:Vec<Window>=Vec::with_capacity(4);for(index,saved)in prepared.saved.entries().iter().enumerate(){if !prepared.eligible[index]{continue;}let mut monitor=saved.monitor().filter(|id|monitors.iter().any(|m|m.id.as_str()==*id)).map(str::to_owned);let mut geometry=saved.geometry();if saved.monitor().is_some()&&monitor.is_none(){issues.push(Issue{index:Some(index as u8),kind:IssueKind::MonitorMissing,monitor:saved.monitor().map(str::to_owned),detail:"The saved monitor is missing; the projector is routed to a window.".into()});geometry=fallback(&monitors,geometry);}else if monitor.is_none()&&geometry.is_some_and(|g|!monitors.iter().any(|m|contains(m,g))){geometry=fallback(&monitors,geometry);issues.push(Issue{index:Some(index as u8),kind:IssueKind::GeometryRelocated,monitor:None,detail:"The saved window is outside the current monitor bounds; windowed placement was adjusted.".into()});}
  if prepared.limit_fullscreen{if let Some(id)=&monitor{let before=windows.len();windows.retain(|window|window.monitor.as_ref()!=Some(id));if windows.len()!=before{issues.push(Issue{index:Some(index as u8),kind:IssueKind::FullscreenReplaced,monitor:Some(id.clone()),detail:"The later saved fullscreen projector replaces the earlier one on this monitor.".into()});}}}
  // Geometry is only applied in windowed mode, as in the original OBS path.
  if monitor.is_some(){geometry=None;}windows.push(Window{saved:saved.clone(),monitor:monitor.take(),geometry});
 }Ok(Resolved{prepared,monitors,windows,issues})}
